import{_ as e,o as l,c as a,a2 as r}from"./chunks/framework.CZGNF-7T.js";const c=JSON.parse('{"title":"계약 실적 관리","description":"","frontmatter":{},"headers":[],"relativePath":"sales/index.md","filePath":"sales/index.md","lastUpdated":1788792702000}'),n={name:"sales/index.md"};function s(d,t,o,i,g,x){return l(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="계약-실적-관리" tabindex="-1">계약 실적 관리 <a class="header-anchor" href="#계약-실적-관리" aria-label="Permalink to &quot;계약 실적 관리&quot;">​</a></h1><p>프로젝트의 분양 계약 건에 대해 담당 영업 인력(상담사, 소속 팀) 및 공인중개사(MGM)를 매핑하고, 실시간 영업 배정률 및 실적을 추적 관리하는 페이지입니다.</p><ul><li><strong>위치</strong>: <code>PJT 관리 시스템 &gt; 분양 대행 관리 &gt; 계약 실적 관리</code></li></ul><h2 id="개요" tabindex="-1">개요 <a class="header-anchor" href="#개요" aria-label="Permalink to &quot;개요&quot;">​</a></h2><p>프로젝트에서 체결되는 모든 계약 건을 영업 조직과 유기적으로 연결하여 누가 어떤 계약을 유치했는지 실적을 투명하게 관리합니다. 계약 건별 담당 상담사와 소속 팀, 적용할 수수료 정책, 성과 인정일을 지정하고, 외부 공인중개사가 연계된 경우 MGM 소개 정보도 함께 자산화합니다. 이 데이터는 향후 <strong>수수료 정산 관리</strong> 시 인센티브를 산출하는 기본 원천 데이터가 됩니다.</p><h2 id="주요-기능" tabindex="-1">주요 기능 <a class="header-anchor" href="#주요-기능" aria-label="Permalink to &quot;주요 기능&quot;">​</a></h2><ul><li><strong>실적 KPI 대시보드</strong>: 프로젝트 전체 계약 건수, 영업 담당자 배정 건수, 배정률(%), MGM 연계 건수 실시간 집계</li><li><strong>계약 실적 대장 조회</strong>: 계약 정보(일련번호, 계약자명, 유니트 동호수)와 매핑된 영업 인력 현황 통합 조회</li><li><strong>다양한 필터링 및 검색</strong>: 배정 상태(전체/배정 완료/미배정), 소속 팀, 담당 상담사별 필터 및 계약자/동호수 키워드 검색</li><li><strong>담당자 배정 및 수정</strong>: 미배정 계약에 대한 신규 영업 담당자 배정 또는 기 배정된 담당자/정책/MGM 정보 수정</li></ul><h2 id="화면-구성" tabindex="-1">화면 구성 <a class="header-anchor" href="#화면-구성" aria-label="Permalink to &quot;화면 구성&quot;">​</a></h2><h3 id="_1-상단-실적-kpi-대시보드" tabindex="-1">1. 상단 실적 KPI 대시보드 <a class="header-anchor" href="#_1-상단-실적-kpi-대시보드" aria-label="Permalink to &quot;1. 상단 실적 KPI 대시보드&quot;">​</a></h3><p>선택된 프로젝트의 분양 계약 및 영업 인력 배정 진척도를 한눈에 파악할 수 있는 요약 카드를 제공합니다.</p><ul><li><strong>총 분양 계약 건수</strong>: 현재 프로젝트에서 체결된 총 계약 건수</li><li><strong>영업 담당 배정 건수</strong>: 영업 인력이 배정 완료된 계약 건수</li><li><strong>담당자 배정률</strong>: 총 계약 대비 영업 담당자 배정 완료 비율(%)</li><li><strong>MGM 연계 계약 건수</strong>: 공인중개사 소개(MGM)로 체결된 계약 건수</li></ul><h3 id="_2-목록-제어-및-검색-툴바" tabindex="-1">2. 목록 제어 및 검색 툴바 <a class="header-anchor" href="#_2-목록-제어-및-검색-툴바" aria-label="Permalink to &quot;2. 목록 제어 및 검색 툴바&quot;">​</a></h3><ul><li><strong>매핑 상태 필터</strong>: 전체 계약, 배정 완료 계약, 미배정 계약 선택</li><li><strong>소속 팀 필터</strong>: 특정 영업 조직/팀으로 필터링</li><li><strong>담당 상담사 필터</strong>: 특정 영업 상담사로 필터링</li><li><strong>통합 검색창</strong>: 계약자명, 동호수, 계약 일련번호, 상담사명 등으로 빠른 검색</li><li><strong>[담당자 배정] 버튼</strong>: 신규로 계약과 영업 담당자를 매핑하는 모달 호출</li></ul><h3 id="_3-계약-실적-영업-담당자-매핑-대장-테이블" tabindex="-1">3. 계약 실적 &amp; 영업 담당자 매핑 대장 테이블 <a class="header-anchor" href="#_3-계약-실적-영업-담당자-매핑-대장-테이블" aria-label="Permalink to &quot;3. 계약 실적 &amp; 영업 담당자 매핑 대장 테이블&quot;">​</a></h3><p>필터링 조건에 부합하는 계약 목록과 각 계약에 매핑된 영업 담당자 정보를 테이블로 표시합니다.</p><table tabindex="0"><thead><tr><th style="text-align:left;">항목</th><th style="text-align:left;">설명</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>계약 정보</strong></td><td style="text-align:left;">계약 일련번호, 계약자 성명, 동호수 및 유니트 정보</td></tr><tr><td style="text-align:left;"><strong>담당 영업직원</strong></td><td style="text-align:left;">계약을 유치한 담당 분양상담사 성명 (미배정 시 붉은색 뱃지 표시)</td></tr><tr><td style="text-align:left;"><strong>소속 팀</strong></td><td style="text-align:left;">담당 상담사가 소속된 영업 본부/팀명</td></tr><tr><td style="text-align:left;"><strong>적용 수수료 정책</strong></td><td style="text-align:left;">해당 계약에 적용될 수수료 정책(R값) 명칭</td></tr><tr><td style="text-align:left;"><strong>성과 인정일</strong></td><td style="text-align:left;">영업 실적으로 인정되는 기준 일자</td></tr><tr><td style="text-align:left;"><strong>MGM 연계 정보</strong></td><td style="text-align:left;">연계된 공인중개사/소개자 상호 및 연락처 (해당 시 표출)</td></tr><tr><td style="text-align:left;"><strong>관리 액션</strong></td><td style="text-align:left;"><code>[수정]</code> (기존 배정 정보 변경) 또는 <code>[배정하기]</code> (신규 담당자 지정)</td></tr></tbody></table><h3 id="_4-영업-담당자-배정-수정-모달-contractagentmodal" tabindex="-1">4. 영업 담당자 배정/수정 모달 (ContractAgentModal) <a class="header-anchor" href="#_4-영업-담당자-배정-수정-모달-contractagentmodal" aria-label="Permalink to &quot;4. 영업 담당자 배정/수정 모달 (ContractAgentModal)&quot;">​</a></h3><p>계약 건에 영업 담당자를 연결하거나 기존 매핑 정보를 수정하는 입력 팝업창입니다.</p><table tabindex="0"><thead><tr><th style="text-align:left;">입력 항목</th><th style="text-align:center;">필수 여부</th><th style="text-align:left;">설명 및 비고</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>대상 계약 선택</strong></td><td style="text-align:center;">필수</td><td style="text-align:left;">담당자를 지정할 분양 계약 건 선택 (미배정 계약 우선 선택)</td></tr><tr><td style="text-align:left;"><strong>담당 영업 상담사</strong></td><td style="text-align:center;">필수</td><td style="text-align:left;">계약을 성사시킨 영업 인력(상담사) 선택</td></tr><tr><td style="text-align:left;"><strong>소속 팀</strong></td><td style="text-align:center;">자동/선택</td><td style="text-align:left;">상담사 선택 시 소속 팀이 자동 연동되며, 필요 시 수동 변경 가능</td></tr><tr><td style="text-align:left;"><strong>수수료 정책</strong></td><td style="text-align:center;">필수</td><td style="text-align:left;">해당 계약에 적용할 수수료 정책 기준표 선택</td></tr><tr><td style="text-align:left;"><strong>영업 성과 인정일</strong></td><td style="text-align:center;">선택</td><td style="text-align:left;">실적으로 인정할 일자 (<code>DatePicker</code> 캘린더 입력)</td></tr><tr><td style="text-align:left;"><strong>MGM 성명/상호</strong></td><td style="text-align:center;">선택</td><td style="text-align:left;">고객을 소개한 외부 공인중개사 상호 또는 성명</td></tr><tr><td style="text-align:left;"><strong>MGM 연락처</strong></td><td style="text-align:center;">선택</td><td style="text-align:left;">공인중개사 휴대전화 번호</td></tr><tr><td style="text-align:left;"><strong>비고</strong></td><td style="text-align:center;">선택</td><td style="text-align:left;">계약 배정 관련 특이사항 및 메모</td></tr></tbody></table>',19)])])}const f=e(n,[["render",s]]);export{c as __pageData,f as default};
